const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { summary: aiResponse, overall_risk: 'unknown', clauses: [], risks: [], obligations: [] };
}
const clausesSummary = (parsed.clauses || []).map(c => `${c.name} [${c.risk_level}]: ${c.description}`).join('\n');
const risksSummary = (parsed.risks || []).map(r => `[${r.severity}] ${r.description} (${r.affected_party})`).join('\n');
const obligationsSummary = (parsed.obligations || []).map(o => `${o.party}: ${o.obligation} (by ${o.deadline || 'N/A'})`).join('\n');
return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    contractType: parsed.contract_type || 'Unknown',
    parties: Array.isArray(parsed.parties) ? parsed.parties.join(' / ') : '',
    overallRisk: parsed.overall_risk || 'unknown',
    summary: parsed.summary || '',
    clauses: clausesSummary,
    risks: risksSummary,
    obligations: obligationsSummary,
    unusualTerms: Array.isArray(parsed.unusual_terms) ? parsed.unusual_terms.join('; ') : '',
    missingClauses: Array.isArray(parsed.missing_clauses) ? parsed.missing_clauses.join('; ') : ''
  }
}];
